// M4 art gallery: the real character candidates (generated by npm run assets:build) side by side for human review.
// Separate page (art.html); does not touch the multiplayer client. Data comes from /art-assets/catalog.json.
import '../zod-jitless.ts'; // first: @bar/game-core pulls in Zod schemas (CSP without 'unsafe-eval')
import { GREYBOX_BAR } from '@bar/game-core';
import {
  type AnimationAction,
  type AnimationClip,
  AnimationMixer,
  type Bone,
  Box3,
  CircleGeometry,
  Color,
  DirectionalLight,
  Fog,
  GridHelper,
  Group,
  HemisphereLight,
  type Light,
  type Material,
  Mesh,
  MeshBasicMaterial,
  MeshStandardMaterial,
  type Object3D,
  PerspectiveCamera,
  PointLight,
  Scene,
  Skeleton,
  type SkinnedMesh,
  SRGBColorSpace,
  type Texture,
  Timer,
  Vector3,
  WebGLRenderer,
} from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { MeshoptDecoder } from 'three/examples/jsm/libs/meshopt_decoder.module.js';
import { type GLTF, GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { clone as cloneSkinned } from 'three/examples/jsm/utils/SkeletonUtils.js';
import { TechnicalAvatar } from '../avatar/technical-avatar.ts';
import { LevelView } from '../render/level-view.ts';
import { type Candidate, loadCatalog } from './catalog.ts';

const ASSETS = '/art-assets/';
const LINEUP_GAP = 1.6;
type MaterialMode = 'pbr' | 'wire' | 'unlit' | 'clay';
type LightMode = 'studio' | 'bar' | 'night';
type Stage = 'studio' | 'bar';
type Role = 'idle' | 'walk' | 'run';
const MATERIAL_LABEL: Record<MaterialMode, string> = {
  pbr: 'Original',
  wire: 'Wireframe',
  unlit: 'Só textura',
  clay: 'Cinza (forma)',
};
const LIGHT_LABEL: Record<LightMode, string> = { studio: 'Estúdio', bar: 'Bar (luz do M1)', night: 'Noite (neon)' };

declare global {
  interface Window {
    /** Diagnostics for the gallery E2E. */
    __art?: { ready: boolean; state: () => unknown };
  }
}

// --- loading ---------------------------------------------------------------------------------------------------

const loader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
const cache = new Map<string, Promise<GLTF>>();
const load = (file: string) => {
  let p = cache.get(file);
  if (!p) {
    p = loader.loadAsync(ASSETS + file);
    cache.set(file, p);
  }
  return p;
};

/** One rendered instance of a candidate variant (+ optional hair) with its own mixer. */
class Character {
  readonly root = new Group();
  readonly clips: AnimationClip[];
  private readonly mixer: AnimationMixer;
  private readonly bones = new Map<string, Bone>();
  private readonly originals = new Map<Mesh, Material | Material[]>();
  private readonly overrides: Material[] = [];
  private action: AnimationAction | undefined;
  private readonly parts = new Map<string, Object3D>();
  clip = '';

  constructor(gltf: GLTF, clips: AnimationClip[]) {
    const model = cloneSkinned(gltf.scene);
    this.root.add(model);
    model.traverse((o) => {
      if ((o as Bone).isBone) this.bones.set(o.name, o as Bone);
      if ((o as Mesh).isMesh) {
        o.castShadow = true;
        o.frustumCulled = false; // skinned bounds do not follow animation
      }
    });
    this.clips = clips;
    this.mixer = new AnimationMixer(model);
  }

  play(name: string): void {
    const clip = this.clips.find((c) => c.name === name) ?? this.clips[0];
    if (!clip || clip.name === this.clip) return;
    const next = this.mixer.clipAction(clip);
    next.reset().play();
    if (this.action) next.crossFadeFrom(this.action, 0.2, false);
    this.action = next;
    this.clip = clip.name;
  }

  set paused(p: boolean) {
    if (this.action) this.action.paused = p;
  }

  update(dt: number): void {
    this.mixer.update(dt);
  }

  /** Sum of bone rotations: changes over time only if the clip really drives the skeleton (E2E check). */
  poseSignature(): number {
    let sum = 0;
    for (const b of this.bones.values()) sum += b.quaternion.x + b.quaternion.y * 3 + b.quaternion.z * 7;
    return sum;
  }

  /** Modular part (hair, outfit): skinned meshes authored on the same skeleton, re-bound to our bones by name. */
  setPart(slot: string, gltf: GLTF | undefined): void {
    this.parts.get(slot)?.removeFromParent();
    this.parts.delete(slot);
    if (!gltf) return;
    const part = cloneSkinned(gltf.scene);
    part.traverse((o) => {
      const m = o as SkinnedMesh;
      if (!m.isSkinnedMesh) return;
      const bones = m.skeleton.bones.map((b) => this.bones.get(b.name) ?? b);
      m.bind(new Skeleton(bones, m.skeleton.boneInverses), m.bindMatrix);
      m.frustumCulled = false;
      m.castShadow = true;
    });
    this.root.add(part);
    this.parts.set(slot, part);
    if (this.mode !== 'pbr') this.setMaterialMode(this.mode);
  }

  private mode: MaterialMode = 'pbr';
  setMaterialMode(mode: MaterialMode): void {
    this.mode = mode;
    for (const m of this.overrides.splice(0)) m.dispose();
    this.root.traverse((o) => {
      const mesh = o as Mesh;
      if (!mesh.isMesh) return;
      if (!this.originals.has(mesh)) this.originals.set(mesh, mesh.material);
      const original = this.originals.get(mesh)!;
      if (mode === 'pbr') {
        mesh.material = original;
        return;
      }
      const src = (Array.isArray(original) ? original[0] : original) as MeshStandardMaterial;
      const m =
        mode === 'wire'
          ? new MeshBasicMaterial({ color: 0x9fe0ff, wireframe: true })
          : mode === 'unlit'
            ? new MeshBasicMaterial({ map: src.map ?? null, color: src.map ? 0xffffff : src.color })
            : new MeshStandardMaterial({ color: 0xb8b2aa, roughness: 0.85 });
      this.overrides.push(m);
      mesh.material = m;
    });
  }

  /** Textures actually used (for thumbnails and the stats panel). */
  textures(): { slot: string; tex: Texture }[] {
    const out: { slot: string; tex: Texture }[] = [];
    const seen = new Set<Texture>();
    for (const mat of this.originals.size ? [...this.originals.values()].flat() : collectMaterials(this.root)) {
      for (const slot of ['map', 'normalMap', 'roughnessMap', 'metalnessMap', 'emissiveMap', 'aoMap'] as const) {
        const tex = (mat as MeshStandardMaterial)[slot];
        if (tex && !seen.has(tex)) {
          seen.add(tex);
          out.push({ slot, tex });
        }
      }
    }
    return out;
  }

  dispose(): void {
    this.setMaterialMode('pbr');
    this.mixer.stopAllAction();
    this.mixer.uncacheRoot(this.root);
    this.root.removeFromParent();
  }
}

function collectMaterials(root: Object3D): Material[] {
  const mats: Material[] = [];
  root.traverse((o) => {
    const m = (o as Mesh).material;
    if (m) mats.push(...(Array.isArray(m) ? m : [m]));
  });
  return mats;
}

// --- scene ---------------------------------------------------------------------------------------------------------

const canvas = document.querySelector<HTMLCanvasElement>('#view')!;
const panel = document.querySelector<HTMLElement>('#panel')!;
const statsEl = document.querySelector<HTMLElement>('#stats')!;
const back = document.querySelector<HTMLAnchorElement>('#back')!;
// npm run demo:art is its own dev server (multiplayer on :5173); the remote gateway serves both pages on one origin.
if (import.meta.env.DEV && location.port !== '5173') back.href = `${location.protocol}//${location.hostname}:5173/`;

const renderer = new WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.outputColorSpace = SRGBColorSpace;
renderer.shadowMap.enabled = true;
const scene = new Scene();
const camera = new PerspectiveCamera(45, 1, 0.05, 80);
const controls = new OrbitControls(camera, canvas);
controls.enableDamping = true;
controls.minDistance = 0.6;
controls.maxDistance = 14;

const stageRoot = new Group();
scene.add(stageRoot);
const studioFloor = new Mesh(new CircleGeometry(4, 48), new MeshStandardMaterial({ color: 0x55504a, roughness: 0.95 }));
studioFloor.rotation.x = -Math.PI / 2;
studioFloor.receiveShadow = true;
const grid = new GridHelper(8, 16, 0x8a7a6a, 0x4a4038);
grid.position.y = 0.002;
let level: LevelView | undefined;
const lights: Light[] = [];

function setLights(mode: LightMode): void {
  for (const l of lights.splice(0)) {
    l.removeFromParent();
    l.dispose();
  }
  const add = (l: Light) => {
    lights.push(l);
    scene.add(l);
    return l;
  };
  const target = focusPoint();
  if (mode === 'studio') {
    scene.background = new Color(0x3b3d42);
    scene.fog = null;
    add(new HemisphereLight(0xffffff, 0x404040, 1.3));
    const key = add(new DirectionalLight(0xffffff, 2.4)) as DirectionalLight;
    key.position.set(target.x - 3, 5, target.z + 4);
    key.castShadow = true;
    const rim = add(new DirectionalLight(0xdfe8ff, 1.4));
    rim.position.set(target.x + 2, 3, target.z - 4);
  } else if (mode === 'bar') {
    // Same values as the M1 scene (RenderStage): what players will actually see.
    scene.background = new Color(0x1a1410);
    scene.fog = new Fog(0x1a1410, 18, 40);
    add(new HemisphereLight(0xffe8cc, 0x2a2018, 1.4));
    const sun = add(new DirectionalLight(0xfff1dd, 2.2)) as DirectionalLight;
    sun.position.set(6, 12, 5);
    sun.castShadow = true;
    Object.assign(sun.shadow.camera, { left: -13, right: 13, top: 13, bottom: -13, near: 1, far: 30 });
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.bias = -0.0005;
    sun.shadow.normalBias = 0.02;
  } else {
    scene.background = new Color(0x0d0a14);
    scene.fog = new Fog(0x0d0a14, 10, 30);
    add(new HemisphereLight(0x6a5a8a, 0x100810, 0.45));
    const pink = add(new PointLight(0xff3d9a, 18, 12)) as PointLight;
    pink.position.set(target.x - 2.2, 2.6, target.z + 1.5);
    const cyan = add(new PointLight(0x2de0ff, 14, 12)) as PointLight;
    cyan.position.set(target.x + 2.4, 2.2, target.z - 1);
    const warm = add(new PointLight(0xffb060, 10, 8)) as PointLight;
    warm.position.set(target.x, 3, target.z + 3);
  }
}

function setStage(stage: Stage): void {
  stageRoot.clear();
  if (stage === 'studio') {
    level?.dispose();
    level = undefined;
    stageRoot.add(studioFloor, grid);
  } else {
    level ??= new LevelView(GREYBOX_BAR, true);
    stageRoot.add(level.root);
  }
}

// --- state ---------------------------------------------------------------------------------------------------------

const catalog = await loadCatalog(ASSETS);
const state = {
  candidate: 0,
  variant: catalog.candidates.map((c) => c.variants[0]!.id),
  /** Chosen part per candidate and slot ('' = none). */
  parts: catalog.candidates.map(() => new Map<string, string>()),
  lineup: false,
  role: 'idle' as Role,
  clip: '',
  paused: false,
  material: 'pbr' as MaterialMode,
  light: 'bar' as LightMode,
  stage: 'studio' as Stage,
  reference: true,
};
let actors: { character: Character; candidate: Candidate; label: string }[] = [];
let reference: TechnicalAvatar | undefined;
const labels: HTMLDivElement[] = [];

/** Characters stand at the M1 spawn in the bar, at the origin in the studio. */
function basePosition(): Vector3 {
  return state.stage === 'bar' ? new Vector3(GREYBOX_BAR.spawn.x, 0, GREYBOX_BAR.spawn.z) : new Vector3(0, 0, 0);
}
function focusPoint(): Vector3 {
  return basePosition().add(new Vector3(0, 0.95, 0));
}

async function clipsFor(c: Candidate, gltf: GLTF): Promise<AnimationClip[]> {
  if (!c.animationLibrary) return gltf.animations;
  return (await load(c.animationLibrary.file)).animations;
}

const partsFor = (c: Candidate, variantId: string) => c.parts.filter((p) => p.for === null || p.for === variantId);
const slotsOf = (c: Candidate, variantId: string) => [...new Set(partsFor(c, variantId).map((p) => p.slot))];
/** Chosen part for a slot; defaults to the first piece that fits the variant. */
function chosenPart(i: number, variantId: string, slot: string): string {
  const c = catalog.candidates[i]!;
  const picked = state.parts[i]!.get(`${variantId}/${slot}`);
  return picked ?? partsFor(c, variantId).find((p) => p.slot === slot)?.id ?? '';
}

async function instantiate(i: number, variantId: string): Promise<Character> {
  const c = catalog.candidates[i]!;
  const v = c.variants.find((x) => x.id === variantId) ?? c.variants[0]!;
  const gltf = await load(v.file);
  const ch = new Character(gltf, await clipsFor(c, gltf));
  for (const slot of slotsOf(c, v.id)) {
    const part = c.parts.find((p) => p.id === chosenPart(i, v.id, slot));
    if (part) ch.setPart(slot, await load(part.file));
  }
  return ch;
}

const roleClip = (c: Candidate, role: Role) => c[role];

async function rebuild(): Promise<void> {
  for (const a of actors) a.character.dispose();
  actors = [];
  reference?.dispose();
  reference = undefined;
  const base = basePosition();
  const list = state.lineup ? catalog.candidates.map((_, i) => i) : [state.candidate];
  const span = (list.length - 1 + (state.reference ? 1 : 0)) * LINEUP_GAP;
  let x = base.x - span / 2;
  for (const i of list) {
    const c = catalog.candidates[i]!;
    const variantId = state.lineup
      ? (c.variants.find((v) => v.id === c.reference)?.id ?? c.variants[0]!.id)
      : state.variant[i]!;
    const ch = await instantiate(i, variantId);
    ch.root.position.set(x, 0, base.z);
    scene.add(ch.root);
    ch.setMaterialMode(state.material);
    ch.play(state.lineup || !state.clip ? roleClip(c, state.role) : state.clip);
    ch.paused = state.paused;
    actors.push({ character: ch, candidate: c, label: `${c.name.split(' ')[0]} · ${variantId}` });
    x += LINEUP_GAP;
  }
  if (state.reference) {
    reference = new TechnicalAvatar(undefined, true);
    reference.setPose({ x, y: 0, z: base.z }, 0);
    reference.setLocomotion(state.role, state.role === 'run' ? 5 : 2.2);
    scene.add(reference.object);
  }
  if (!state.lineup) state.clip = actors[0]!.character.clip;
  renderLabels();
  renderPanel();
}

function renderLabels(): void {
  for (const l of labels.splice(0)) l.remove();
  const items = [...actors.map((a) => a.label), ...(reference ? ['Referência M1 · 1,75 m'] : [])];
  for (const text of items) {
    const el = document.createElement('div');
    el.className = 'label';
    el.textContent = text;
    document.body.append(el);
    labels.push(el);
  }
}

function view(kind: 'front' | 'profile' | 'back'): void {
  const t = focusPoint();
  const d = state.lineup ? 6.5 : 3.2;
  const dir =
    kind === 'front'
      ? new Vector3(0, 0.15, 1)
      : kind === 'profile'
        ? new Vector3(1, 0.15, 0)
        : new Vector3(0, 0.15, -1);
  controls.target.copy(t);
  camera.position.copy(t).addScaledVector(dir.normalize(), d);
  controls.update();
}

// --- panel ---------------------------------------------------------------------------------------------------------

const kb = (n: number) => `${(n / 1024).toFixed(0)} KB`;
function button(label: string, pressed: boolean, onClick: () => void, title?: string): HTMLButtonElement {
  const b = document.createElement('button');
  b.type = 'button';
  b.textContent = label;
  b.setAttribute('aria-pressed', String(pressed));
  if (title) b.title = title;
  b.addEventListener('click', onClick);
  return b;
}
function select(
  label: string,
  options: [string, string][],
  value: string,
  onChange: (v: string) => void,
): HTMLLabelElement {
  const l = document.createElement('label');
  l.className = 'row';
  l.append(`${label} `);
  const s = document.createElement('select');
  for (const [v, text] of options) s.add(new Option(text, v, false, v === value));
  s.addEventListener('change', () => onChange(s.value));
  l.append(s);
  return l;
}
const section = (title: string) => {
  const h = document.createElement('h2');
  h.textContent = title;
  panel.append(h);
};
const row = (...children: HTMLElement[]) => {
  const d = document.createElement('div');
  d.className = 'row';
  d.append(...children);
  panel.append(d);
  return d;
};
const para = (html: string, cls = '') => {
  const p = document.createElement('p');
  if (cls) p.className = cls;
  p.innerHTML = html;
  panel.append(p);
};
const esc = (s: string) => s.replace(/[&<>"]/g, (ch) => `&#${ch.charCodeAt(0)};`);

function renderPanel(): void {
  panel.replaceChildren();
  const h1 = document.createElement('h1');
  h1.textContent = 'Candidatos a personagem — M4';
  panel.append(h1);
  para('Escolha visual pendente: <strong>nenhum candidato está aprovado</strong>.', 'muted');

  section('Candidato');
  row(
    ...catalog.candidates.map((c, i) =>
      button(`${i + 1}. ${c.name.split(':')[0]!.split('(')[0]!.trim()}`, !state.lineup && state.candidate === i, () => {
        state.candidate = i;
        state.lineup = false;
        state.clip = '';
        void rebuild();
      }),
    ),
    button('Lado a lado', state.lineup, () => {
      state.lineup = !state.lineup;
      void rebuild().then(() => view('front'));
    }),
  );

  const c = catalog.candidates[state.candidate]!;
  if (!state.lineup) {
    row(
      select(
        'Variante',
        c.variants.map((v) => [v.id, v.id]),
        state.variant[state.candidate]!,
        (v) => {
          state.variant[state.candidate] = v;
          void rebuild();
        },
      ),
    );
    const vid = state.variant[state.candidate]!;
    for (const slot of slotsOf(c, vid)) {
      const options = partsFor(c, vid).filter((p) => p.slot === slot);
      row(
        select(
          `${slot === 'hair' ? 'Cabelo' : slot === 'outfit' ? 'Traje' : slot} (peça modular)`,
          [['', 'nenhum'], ...options.map((p): [string, string] => [p.id, p.id])],
          chosenPart(state.candidate, vid, slot),
          (v) => {
            state.parts[state.candidate]!.set(`${vid}/${slot}`, v);
            void rebuild();
          },
        ),
      );
    }
  }

  section('Animação');
  if (state.lineup) {
    row(
      ...(['idle', 'walk', 'run'] as Role[]).map((r) =>
        button(r, state.role === r, () => {
          state.role = r;
          void rebuild();
        }),
      ),
    );
  } else {
    const clips = actors[0]?.character.clips ?? [];
    row(
      select(
        'Clipe',
        clips.map((k) => [k.name, `${k.name} (${k.duration.toFixed(1)} s)`]),
        state.clip,
        (v) => {
          state.clip = v;
          actors[0]?.character.play(v);
        },
      ),
    );
    para(
      `${clips.length} clipes · papéis no jogo: idle=${esc(c.idle)}, walk=${esc(c.walk)}, run=${esc(c.run)}`,
      'muted',
    );
  }
  row(
    button(state.paused ? '▶ Continuar' : '⏸ Pausar', state.paused, () => togglePause()),
    button('Referência 1,75 m', state.reference, () => {
      state.reference = !state.reference;
      void rebuild();
    }),
  );

  section('Câmera e luz');
  row(
    button('Frente (F)', false, () => view('front')),
    button('Perfil (P)', false, () => view('profile')),
    button('Costas (C)', false, () => view('back')),
  );
  row(
    ...(Object.keys(LIGHT_LABEL) as LightMode[]).map((m) =>
      button(LIGHT_LABEL[m], state.light === m, () => setLight(m)),
    ),
  );
  row(
    button('Estúdio', state.stage === 'studio', () => setStageMode('studio')),
    button('Bar (greybox M1)', state.stage === 'bar', () => setStageMode('bar')),
  );
  row(
    ...(Object.keys(MATERIAL_LABEL) as MaterialMode[]).map((m) =>
      button(MATERIAL_LABEL[m], state.material === m, () => setMaterial(m)),
    ),
  );

  if (state.lineup) {
    section('Comparação');
    for (const x of catalog.candidates) {
      const v = x.variants.find((y) => y.id === x.reference) ?? x.variants[0]!;
      para(
        `<strong>${esc(x.name)}</strong> — ${v.triangles} tris · ${v.joints} juntas · ${(x.animationLibrary ?? v).animations.length} clipes · ${kb(v.bytes)} · ${esc(x.license)}`,
      );
    }
    return;
  }
  const v = c.variants.find((x) => x.id === state.variant[state.candidate]) ?? c.variants[0]!;
  section('Origem e licença');
  const dl = document.createElement('dl');
  const item = (k: string, val: string) => dl.insertAdjacentHTML('beforeend', `<dt>${k}</dt><dd>${val}</dd>`);
  item('Pacote', esc(c.name));
  item('Autor', esc(c.author));
  item(
    'Fonte',
    `<a href="${esc(c.page)}" target="_blank" rel="noopener noreferrer">${esc(c.page.replace(/^https:\/\//, ''))}</a>`,
  );
  item('Licença', esc(c.license));
  item('Atribuição', esc(c.attribution));
  item('Estilo', esc(c.style));
  panel.append(dl);
  for (const ev of c.licenseEvidence) {
    const q = document.createElement('blockquote');
    q.textContent = `${ev.file}: ${ev.excerpt.join(' / ')}`;
    panel.append(q);
  }

  section('Técnico (arquivo gerado)');
  const t = document.createElement('dl');
  const it = (k: string, val: string) => t.insertAdjacentHTML('beforeend', `<dt>${k}</dt><dd>${val}</dd>`);
  it('Tamanho', `${kb(v.bytes)} (original ${kb(v.originalBytes)})`);
  it('Geometria', `${v.triangles} triângulos · ${v.vertices} vértices`);
  it('Esqueleto', `${v.joints} juntas`);
  it(
    'Animações',
    `${(c.animationLibrary ?? v).animations.length}${c.animationLibrary ? ' (biblioteca compartilhada)' : ''}`,
  );
  it('Materiais', esc(v.materials.map((m) => m.name || '—').join(', ')));
  it('Texturas', esc(v.textures.map((x) => `${x.name ?? '?'} ${x.size ?? ''} ${x.mime}`).join(' · ') || 'nenhuma'));
  it('Altura', `${v.height} m (pacote ×${c.scale.toFixed(3)})`);
  it('Validador', `${v.validation.errors} erros · ${v.validation.warnings} avisos`);
  panel.append(t);
  const thumbs = document.createElement('div');
  thumbs.className = 'thumbs';
  for (const { slot, tex } of actors[0]?.character.textures() ?? []) {
    const fig = document.createElement('figure');
    const cv = document.createElement('canvas');
    cv.width = cv.height = 64;
    const img = tex.image as CanvasImageSource | undefined;
    if (img) cv.getContext('2d')?.drawImage(img, 0, 0, 64, 64);
    fig.append(cv, slot);
    thumbs.append(fig);
  }
  panel.append(thumbs);
  para(`Modificações: ${v.modifications.map(esc).join('; ')}`, 'muted');
}

function togglePause(): void {
  state.paused = !state.paused;
  for (const a of actors) a.character.paused = state.paused;
  renderPanel();
}
function setLight(m: LightMode): void {
  state.light = m;
  setLights(m);
  renderPanel();
}
function setMaterial(m: MaterialMode): void {
  state.material = m;
  for (const a of actors) a.character.setMaterialMode(m);
  renderPanel();
}
function setStageMode(s: Stage): void {
  state.stage = s;
  setStage(s);
  setLights(state.light);
  void rebuild().then(() => view('front'));
}
function stepClip(dir: number): void {
  const ch = actors[0]?.character;
  if (state.lineup || !ch || ch.clips.length === 0) return;
  const i = ch.clips.findIndex((k) => k.name === state.clip);
  state.clip = ch.clips[(i + dir + ch.clips.length) % ch.clips.length]!.name;
  ch.play(state.clip);
  renderPanel();
}

window.addEventListener('keydown', (e) => {
  if (e.target instanceof HTMLSelectElement) return;
  const k = e.key.toLowerCase();
  const n = Number(k);
  if (n >= 1 && n <= catalog.candidates.length) {
    state.candidate = n - 1;
    state.lineup = false;
    state.clip = '';
    void rebuild();
  } else if (k === 'l') {
    state.lineup = !state.lineup;
    void rebuild().then(() => view('front'));
  } else if (k === 'f') view('front');
  else if (k === 'p') view('profile');
  else if (k === 'c') view('back');
  else if (k === ' ') {
    e.preventDefault();
    togglePause();
  } else if (k === 'arrowright') stepClip(1);
  else if (k === 'arrowleft') stepClip(-1);
  else if (k === 'm') {
    const modes = Object.keys(MATERIAL_LABEL) as MaterialMode[];
    setMaterial(modes[(modes.indexOf(state.material) + 1) % modes.length]!);
  } else if (k === 'i') {
    const modes = Object.keys(LIGHT_LABEL) as LightMode[];
    setLight(modes[(modes.indexOf(state.light) + 1) % modes.length]!);
  } else if (k === 'e') setStageMode(state.stage === 'studio' ? 'bar' : 'studio');
  else if (k === 'r') {
    state.reference = !state.reference;
    void rebuild();
  }
});

// --- loop ----------------------------------------------------------------------------------------------------------

function resize(): void {
  const w = window.innerWidth;
  const h = window.innerHeight;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(w, h, false);
  camera.aspect = w / Math.max(h, 1);
  camera.updateProjectionMatrix();
}
window.addEventListener('resize', resize);
resize();

const timer = new Timer();
const frames: number[] = [];
const box = new Box3();
const tmp = new Vector3();
function frame(): void {
  timer.update();
  const dt = Math.min(timer.getDelta(), 0.1);
  frames.push(dt);
  if (frames.length > 120) frames.shift();
  controls.update();
  for (const a of actors) a.character.update(dt);
  reference?.update(dt);
  renderer.render(scene, camera);
  // Labels above heads (measured from the animated pose).
  const objs = [...actors.map((a) => a.character.root), ...(reference ? [reference.object] : [])];
  objs.forEach((o, i) => {
    const el = labels[i];
    if (!el) return;
    box.setFromObject(o, true);
    tmp.set((box.min.x + box.max.x) / 2, box.max.y + 0.08, (box.min.z + box.max.z) / 2).project(camera);
    el.hidden = tmp.z > 1;
    el.style.left = `${((tmp.x + 1) / 2) * window.innerWidth}px`;
    el.style.top = `${((1 - tmp.y) / 2) * window.innerHeight}px`;
  });
  const fps = frames.length / frames.reduce((s, x) => s + x, 0);
  const info = renderer.info;
  statsEl.textContent = [
    `FPS ${fps.toFixed(0)}  ·  draw calls ${info.render.calls}  ·  triângulos ${info.render.triangles}`,
    `geometrias ${info.memory.geometries}  ·  texturas ${info.memory.textures}  ·  shaders ${info.programs?.length ?? 0}`,
    `luz ${LIGHT_LABEL[state.light]}  ·  cenário ${state.stage === 'bar' ? 'bar (greybox M1)' : 'estúdio'}  ·  material ${MATERIAL_LABEL[state.material]}`,
  ].join('\n');
  requestAnimationFrame(frame);
}

function measuredHeights(): number[] {
  return actors.map((a) => {
    box.setFromObject(a.character.root, true);
    return Math.round((box.max.y - box.min.y) * 1000) / 1000;
  });
}

setStage(state.stage);
setLights(state.light);
await rebuild();
view('front');
document.querySelector('#loading')?.remove();
requestAnimationFrame(frame);
window.__art = {
  ready: true,
  state: () => ({
    ...state,
    actors: actors.map((a) => ({
      candidate: a.candidate.id,
      clip: a.character.clip,
      clips: a.character.clips.length,
      pose: a.character.poseSignature(),
    })),
    heights: measuredHeights(),
    render: {
      calls: renderer.info.render.calls,
      triangles: renderer.info.render.triangles,
      textures: renderer.info.memory.textures,
    },
  }),
};
